namespace ghidra.app.plugin.core.data;



using docking.action;
using ghidra.app.context;
using ghidra.app.context;
using ghidra.program.model.data;
using ghidra.util;

/**
 * Base class for actions to create data types
 */
class DataAction : ListingContextAction {

	protected DataType dataType;
	protected DataPlugin plugin;

	public DataAction(DataType dataType, DataPlugin plugin) : this("Define " + dataType.getDisplayName(), "Data", dataType, plugin)
    {
	}

	/**
	 * Constructor
	 * 
	 * @param name action name
	 * @param group the action's group
	 * @param dataType the data type used by this action
	 * @param plugin the plugin that owns this action
	 */
	public DataAction(string name, string group, DataType dataType, DataPlugin plugin) : base(name, plugin.getName(), KeyBindingType.SHARED)
    {
		this.plugin = plugin;
		this.dataType = dataType;

		setPopupMenuData(new MenuData(new string[] { "Data", dataType.getDisplayName() }, group));
		assignHelpID(dataType);
		initKeyStroke(getDefaultKeyStroke());
	}

	protected KeyStroke getDefaultKeyStroke() {
		return null; // we have no default, but our subclasses may
	}

	protected void initKeyStroke(KeyStroke keyStroke) {
		if (keyStroke == null) {
			return;
		}

		setKeyBindingData(new KeyBindingData(keyStroke));
	}

	DataType getDataType() {
		return dataType;
	}

	/* @Override */
	public void dispose() {
		dataType = null;
		plugin = null;
		base.dispose();
	}

	/* @Override */
	public void actionPerformed(ListingActionContext context) {
		plugin.doCreateData(context, dataType, true);
		return;
	}

	/* @Override */
	public bool isEnabledForContext(ListingActionContext context) {
		return plugin.isCreateDataAllowed(context);
	}

	// Set the help ID according to the data type
	private void assignHelpID(DataType dt) {
		string helpID = "Favorites";

		if (dt is Structure) {
			helpID = "Structure";
		}
		else if (dt is Union) {
			helpID = "Union";
		}
		else if (dt is Pointer) {
			helpID = "Define_Pointer";
		}
		else if (dt is Dynamic) {
			helpID = "DynamicDataType";
		}

		setHelpLocation(new HelpLocation(plugin.getName(), helpID));
	}
}
